func (m *TLInputWebDocument) Encode(x *EncodeBuf, layer int32) error {
	clazzId := GetClazzID(Predicate_inputWebDocument, int(layer))
	switch uint32(clazzId) {
	case 0x9bed434d:
		x.UInt(0x9bed434d)

		x.String(m.GetUrl())
		x.Int(m.GetSize2())
		x.String(m.GetMimeType())

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list3 := m.GetAttributes()
			x.Int(int32(len(list3)))
			for _, v := range list3 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		return nil

	default:
		return fmt.Errorf("not found clazzId by (%s, %d)", Predicate_inputWebDocument, layer)
	}
}

