func (m *TLMessageReactions) Encode(x *EncodeBuf, layer int32) error {
	clazzId := GetClazzID(Predicate_messageReactions, int(layer))
	switch uint32(clazzId) {
	case 0xa339f0b:
		x.UInt(0xa339f0b)

		// set flags
		var getFlags = func() uint32 {
			var flags uint32 = 0

			if m.GetMin() == true {
				flags |= 1 << 0
			}
			if m.GetCanSeeList() == true {
				flags |= 1 << 2
			}
			if m.GetReactionsAsTags() == true {
				flags |= 1 << 3
			}

			if m.GetRecentReactions() != nil {
				flags |= 1 << 1
			}
			if m.GetTopReactors() != nil {
				flags |= 1 << 4
			}

			return flags
		}

		// set flags
		var flags = getFlags()
		x.UInt(flags)

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list4 := m.GetResults()
			x.Int(int32(len(list4)))
			for _, v := range list4 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		if m.GetRecentReactions() != nil {
			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				list5 := m.GetRecentReactions()
				x.Int(int32(len(list5)))
				for _, v := range list5 {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}
		}
		if m.GetTopReactors() != nil {
			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				list6 := m.GetTopReactors()
				x.Int(int32(len(list6)))
				for _, v := range list6 {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}
		}

		return nil
	case 0x4f2b9479:
		x.UInt(0x4f2b9479)

		// set flags
		var getFlags = func() uint32 {
			var flags uint32 = 0

			if m.GetMin() == true {
				flags |= 1 << 0
			}
			if m.GetCanSeeList() == true {
				flags |= 1 << 2
			}
			if m.GetReactionsAsTags() == true {
				flags |= 1 << 3
			}

			if m.GetRecentReactions() != nil {
				flags |= 1 << 1
			}

			return flags
		}

		// set flags
		var flags = getFlags()
		x.UInt(flags)

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list4 := m.GetResults()
			x.Int(int32(len(list4)))
			for _, v := range list4 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		if m.GetRecentReactions() != nil {
			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				list5 := m.GetRecentReactions()
				x.Int(int32(len(list5)))
				for _, v := range list5 {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}
		}

		return nil

	default:
		return fmt.Errorf("not found clazzId by (%s, %d)", Predicate_messageReactions, layer)
	}
}

