func (m *TLMessageReactions) Decode(dBuf *DecodeBuf) error {
	switch uint32(m.Data2.Constructor) {
	case 0xa339f0b:
		var flags = dBuf.UInt()
		_ = flags
		if (flags & (1 << 0)) != 0 {
			m.SetMin(true)
		}
		if (flags & (1 << 2)) != 0 {
			m.SetCanSeeList(true)
		}
		if (flags & (1 << 3)) != 0 {
			m.SetReactionsAsTags(true)
		}
		c4 := dBuf.Int()
		if c4 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 4, c4)
			return dBuf.GetError()
		}
		l4 := dBuf.Int()
		if l4 < 0 || l4 > maxVectorLen {
			return fmt.Errorf("invalid vector length: %d", l4)
		}
		v4 := make([]*ReactionCount, l4)
		for i := int32(0); i < l4; i++ {
			v4[i] = &ReactionCount{}
			v4[i].Decode(dBuf)
		}
		m.SetResults(v4)

		if (flags & (1 << 1)) != 0 {
			c5 := dBuf.Int()
			if c5 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 5, c5)
				return dBuf.GetError()
			}
			l5 := dBuf.Int()
			if l5 < 0 || l5 > maxVectorLen {
				return fmt.Errorf("invalid vector length: %d", l5)
			}
			v5 := make([]*MessagePeerReaction, l5)
			for i := int32(0); i < l5; i++ {
				v5[i] = &MessagePeerReaction{}
				v5[i].Decode(dBuf)
			}
			m.SetRecentReactions(v5)
		}
		if (flags & (1 << 4)) != 0 {
			c6 := dBuf.Int()
			if c6 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 6, c6)
				return dBuf.GetError()
			}
			l6 := dBuf.Int()
			if l6 < 0 || l6 > maxVectorLen {
				return fmt.Errorf("invalid vector length: %d", l6)
			}
			v6 := make([]*MessageReactor, l6)
			for i := int32(0); i < l6; i++ {
				v6[i] = &MessageReactor{}
				v6[i].Decode(dBuf)
			}
			m.SetTopReactors(v6)
		}
		return dBuf.GetError()
	case 0x4f2b9479:
		var flags = dBuf.UInt()
		_ = flags
		if (flags & (1 << 0)) != 0 {
			m.SetMin(true)
		}
		if (flags & (1 << 2)) != 0 {
			m.SetCanSeeList(true)
		}
		if (flags & (1 << 3)) != 0 {
			m.SetReactionsAsTags(true)
		}
		c4 := dBuf.Int()
		if c4 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 4, c4)
			return dBuf.GetError()
		}
		l4 := dBuf.Int()
		if l4 < 0 || l4 > maxVectorLen {
			return fmt.Errorf("invalid vector length: %d", l4)
		}
		v4 := make([]*ReactionCount, l4)
		for i := int32(0); i < l4; i++ {
			v4[i] = &ReactionCount{}
			v4[i].Decode(dBuf)
		}
		m.SetResults(v4)

		if (flags & (1 << 1)) != 0 {
			c5 := dBuf.Int()
			if c5 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 5, c5)
				return dBuf.GetError()
			}
			l5 := dBuf.Int()
			if l5 < 0 || l5 > maxVectorLen {
				return fmt.Errorf("invalid vector length: %d", l5)
			}
			v5 := make([]*MessagePeerReaction, l5)
			for i := int32(0); i < l5; i++ {
				v5[i] = &MessagePeerReaction{}
				v5[i].Decode(dBuf)
			}
			m.SetRecentReactions(v5)
		}
		return dBuf.GetError()

	default:
		return fmt.Errorf("invalid constructor: %x", uint32(m.Data2.Constructor))
	}
}

