func (m *TLPage) GetDocuments() []*Document  { return m.Data2.Documents }

func (m *TLPage) SetViews(v *wrapperspb.Int32Value) { m.Data2.Views = v }
func (m *TLPage) GetViews() *wrapperspb.Int32Value  { return m.Data2.Views }

func (m *TLPage) GetPredicateName() string {
	return Predicate_page
}

func (m *TLPage) Encode(x *EncodeBuf, layer int32) error {
	clazzId := GetClazzID(Predicate_page, int(layer))
	switch uint32(clazzId) {
	case 0x98657f0d:
		x.UInt(0x98657f0d)

		// set flags
		var getFlags = func() uint32 {
			var flags uint32 = 0

			if m.GetPart() == true {
				flags |= 1 << 0
			}
			if m.GetRtl() == true {
				flags |= 1 << 1
			}
			if m.GetV2() == true {
				flags |= 1 << 2
			}

			if m.GetViews() != nil {
				flags |= 1 << 3
			}

			return flags
		}

		// set flags
		var flags = getFlags()
		x.UInt(flags)
		x.String(m.GetUrl())

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list5 := m.GetBlocks()
			x.Int(int32(len(list5)))
			for _, v := range list5 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list6 := m.GetPhotos()
			x.Int(int32(len(list6)))
			for _, v := range list6 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list7 := m.GetDocuments()
			x.Int(int32(len(list7)))
			for _, v := range list7 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		if m.GetViews() != nil {
			x.Int(m.GetViews().Value)
		}

		return nil

	default:
		return fmt.Errorf("not found clazzId by (%s, %d)", Predicate_page, layer)
	}
}

func (m *TLPage) CalcByteSize(layer int32) int {
	return 0
}

func (m *TLPage) Decode(dBuf *DecodeBuf) error {
	switch uint32(m.Data2.Constructor) {
	case 0x98657f0d:
		var flags = dBuf.UInt()
		_ = flags
		if (flags & (1 << 0)) != 0 {
			m.SetPart(true)
		}
		if (flags & (1 << 1)) != 0 {
			m.SetRtl(true)
		}
		if (flags & (1 << 2)) != 0 {
			m.SetV2(true)
		}
		m.SetUrl(dBuf.String())
		c5 := dBuf.Int()
		if c5 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 5, c5)
			return dBuf.GetError()
		}
		l5 := dBuf.Int()
		if l5 < 0 || l5 > maxVectorLen {
			return fmt.Errorf("invalid vector length: %d", l5)
		}
		v5 := make([]*PageBlock, l5)
		for i := int32(0); i < l5; i++ {
			v5[i] = &PageBlock{}
			v5[i].Decode(dBuf)
		}
		m.SetBlocks(v5)

		c6 := dBuf.Int()
		if c6 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 6, c6)
			return dBuf.GetError()
		}
		l6 := dBuf.Int()
		if l6 < 0 || l6 > maxVectorLen {
			return fmt.Errorf("invalid vector length: %d", l6)
		}
		v6 := make([]*Photo, l6)
		for i := int32(0); i < l6; i++ {
			v6[i] = &Photo{}
			v6[i].Decode(dBuf)
		}
		m.SetPhotos(v6)

		c7 := dBuf.Int()
		if c7 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 7, c7)
			return dBuf.GetError()
		}
		l7 := dBuf.Int()
		if l7 < 0 || l7 > maxVectorLen {
			return fmt.Errorf("invalid vector length: %d", l7)
		}
		v7 := make([]*Document, l7)
		for i := int32(0); i < l7; i++ {
			v7[i] = &Document{}
			v7[i].Decode(dBuf)
		}
		m.SetDocuments(v7)

		if (flags & (1 << 3)) != 0 {
			m.SetViews(&wrapperspb.Int32Value{Value: dBuf.Int()})
		}

		return dBuf.GetError()

	default:
		return fmt.Errorf("invalid constructor: %x", uint32(m.Data2.Constructor))
	}
}

