func (m *TLSecureValue) Encode(x *EncodeBuf, layer int32) error {
	clazzId := GetClazzID(Predicate_secureValue, int(layer))
	switch uint32(clazzId) {
	case 0x187fa0ca:
		x.UInt(0x187fa0ca)

		// set flags
		var getFlags = func() uint32 {
			var flags uint32 = 0

			if m.GetData() != nil {
				flags |= 1 << 0
			}
			if m.GetFrontSide() != nil {
				flags |= 1 << 1
			}
			if m.GetReverseSide() != nil {
				flags |= 1 << 2
			}
			if m.GetSelfie() != nil {
				flags |= 1 << 3
			}
			if m.GetTranslation() != nil {
				flags |= 1 << 6
			}
			if m.GetFiles() != nil {
				flags |= 1 << 4
			}
			if m.GetPlainData() != nil {
				flags |= 1 << 5
			}

			return flags
		}

		// set flags
		var flags = getFlags()
		x.UInt(flags)
		m.GetType().Encode(x, layer)
		if m.GetData() != nil {
			m.GetData().Encode(x, layer)
		}

		if m.GetFrontSide() != nil {
			m.GetFrontSide().Encode(x, layer)
		}

		if m.GetReverseSide() != nil {
			m.GetReverseSide().Encode(x, layer)
		}

		if m.GetSelfie() != nil {
			m.GetSelfie().Encode(x, layer)
		}

		if m.GetTranslation() != nil {
			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				list6 := m.GetTranslation()
				x.Int(int32(len(list6)))
				for _, v := range list6 {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}
		}
		if m.GetFiles() != nil {
			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				list7 := m.GetFiles()
				x.Int(int32(len(list7)))
				for _, v := range list7 {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}
		}
		if m.GetPlainData() != nil {
			m.GetPlainData().Encode(x, layer)
		}

		x.StringBytes(m.GetHash())

		return nil

	default:
		return fmt.Errorf("not found clazzId by (%s, %d)", Predicate_secureValue, layer)
	}
}

