func (m *TLSecureValue) Decode(dBuf *DecodeBuf) error {
	switch uint32(m.Data2.Constructor) {
	case 0x187fa0ca:
		var flags = dBuf.UInt()
		_ = flags

		m1 := &SecureValueType{}
		m1.Decode(dBuf)
		m.SetType(m1)

		if (flags & (1 << 0)) != 0 {
			m2 := &SecureData{}
			m2.Decode(dBuf)
			m.SetData(m2)
		}
		if (flags & (1 << 1)) != 0 {
			m3 := &SecureFile{}
			m3.Decode(dBuf)
			m.SetFrontSide(m3)
		}
		if (flags & (1 << 2)) != 0 {
			m4 := &SecureFile{}
			m4.Decode(dBuf)
			m.SetReverseSide(m4)
		}
		if (flags & (1 << 3)) != 0 {
			m5 := &SecureFile{}
			m5.Decode(dBuf)
			m.SetSelfie(m5)
		}
		if (flags & (1 << 6)) != 0 {
			c6 := dBuf.Int()
			if c6 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 6, c6)
				return dBuf.GetError()
			}
			l6 := dBuf.Int()
			if l6 < 0 || l6 > maxVectorLen {
				return fmt.Errorf("invalid vector length: %d", l6)
			}
			v6 := make([]*SecureFile, l6)
			for i := int32(0); i < l6; i++ {
				v6[i] = &SecureFile{}
				v6[i].Decode(dBuf)
			}
			m.SetTranslation(v6)
		}
		if (flags & (1 << 4)) != 0 {
			c7 := dBuf.Int()
			if c7 != int32(CRC32_vector) {
				// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 7, c7)
				return dBuf.GetError()
			}
			l7 := dBuf.Int()
			if l7 < 0 || l7 > maxVectorLen {
				return fmt.Errorf("invalid vector length: %d", l7)
			}
			v7 := make([]*SecureFile, l7)
			for i := int32(0); i < l7; i++ {
				v7[i] = &SecureFile{}
				v7[i].Decode(dBuf)
			}
			m.SetFiles(v7)
		}
		if (flags & (1 << 5)) != 0 {
			m8 := &SecurePlainData{}
			m8.Decode(dBuf)
			m.SetPlainData(m8)
		}
		m.SetHash(dBuf.StringBytes())
		return dBuf.GetError()

	default:
		return fmt.Errorf("invalid constructor: %x", uint32(m.Data2.Constructor))
	}
}

