func (m *TLStoryView) GetBlockedMyStoriesFrom() bool  { return m.Data2.BlockedMyStoriesFrom }

func (m *TLStoryView) SetUserId(v int64) { m.Data2.UserId = v }
func (m *TLStoryView) GetUserId() int64  { return m.Data2.UserId }

func (m *TLStoryView) SetDate(v int32) { m.Data2.Date = v }
func (m *TLStoryView) GetDate() int32  { return m.Data2.Date }

func (m *TLStoryView) SetReaction(v *Reaction) { m.Data2.Reaction = v }
func (m *TLStoryView) GetReaction() *Reaction  { return m.Data2.Reaction }

