// // flags
func (m *TLTodoList) SetOthersCanAppend(v bool) { m.Data2.OthersCanAppend = v }
func (m *TLTodoList) GetOthersCanAppend() bool  { return m.Data2.OthersCanAppend }

func (m *TLTodoList) SetOthersCanComplete(v bool) { m.Data2.OthersCanComplete = v }
func (m *TLTodoList) GetOthersCanComplete() bool  { return m.Data2.OthersCanComplete }

func (m *TLTodoList) SetTitle(v *TextWithEntities) { m.Data2.Title = v }
func (m *TLTodoList) GetTitle() *TextWithEntities  { return m.Data2.Title }

func (m *TLTodoList) SetList(v []*TodoItem) { m.Data2.List = v }
func (m *TLTodoList) GetList() []*TodoItem  { return m.Data2.List }

func (m *TLTodoList) GetPredicateName() string {
	return Predicate_todoList
}

func (m *TLTodoList) Encode(x *EncodeBuf, layer int32) error {
	clazzId := GetClazzID(Predicate_todoList, int(layer))
	switch uint32(clazzId) {
	case 0x49b92a26:
		x.UInt(0x49b92a26)

		// set flags
		var getFlags = func() uint32 {
			var flags uint32 = 0

			if m.GetOthersCanAppend() == true {
				flags |= 1 << 0
			}
			if m.GetOthersCanComplete() == true {
				flags |= 1 << 1
			}

			return flags
		}

		// set flags
		var flags = getFlags()
		x.UInt(flags)
		m.GetTitle().Encode(x, layer)

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list4 := m.GetList()
			x.Int(int32(len(list4)))
			for _, v := range list4 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

		return nil

	default:
		return fmt.Errorf("not found clazzId by (%s, %d)", Predicate_todoList, layer)
	}
}

func (m *TLTodoList) CalcByteSize(layer int32) int {
	return 0
}

func (m *TLTodoList) Decode(dBuf *DecodeBuf) error {
	switch uint32(m.Data2.Constructor) {
	case 0x49b92a26:
		var flags = dBuf.UInt()
		_ = flags
		if (flags & (1 << 0)) != 0 {
			m.SetOthersCanAppend(true)
		}
		if (flags & (1 << 1)) != 0 {
			m.SetOthersCanComplete(true)
		}

		m3 := &TextWithEntities{}
		m3.Decode(dBuf)
		m.SetTitle(m3)

		c4 := dBuf.Int()
		if c4 != int32(CRC32_vector) {
			// dBuf.err = fmt.Errorf("invalid CRC32_vector, c%d: %d", 4, c4)
			return dBuf.GetError()
		}
		l4 := dBuf.Int()
		if l4 < 0 || l4 > maxVectorLen {
			return fmt.Errorf("invalid vector length: %d", l4)
		}
		v4 := make([]*TodoItem, l4)
		for i := int32(0); i < l4; i++ {
			v4[i] = &TodoItem{}
			v4[i].Decode(dBuf)
		}
		m.SetList(v4)

		return dBuf.GetError()

	default:
		return fmt.Errorf("invalid constructor: %x", uint32(m.Data2.Constructor))
	}
}

