func (m *TLMessagesTranslateRichMessage) Encode(x *EncodeBuf, layer int32) error {
	switch uint32(m.Constructor) {
	case 0x1a542004:
		x.UInt(0x1a542004)

		// set flags
		var flags uint32 = 0

		if m.GetPeer() != nil {
			flags |= 1 << 0
		}
		if m.GetId() != nil {
			flags |= 1 << 0
		}
		if m.GetText() != nil {
			flags |= 1 << 1
		}

		if m.GetTone() != nil {
			flags |= 1 << 2
		}

		x.UInt(flags)

		// flags Debug by @benqi
		if m.GetPeer() != nil {
			m.GetPeer().Encode(x, layer)
		}

		if m.GetId() != nil {
			x.VectorInt(m.GetId())
		}
		if m.GetText() != nil {
			x.Int(int32(CRC32_vector))
			{
				var (
					sz     = int32(0)
					offset = x.GetOffset()
				)
				list4 := m.GetText()
				x.Int(int32(len(list4)))
				for _, v := range list4 {
					err := v.Encode(x, layer)
					if err == nil {
						sz += 1
					}
				}
				x.IntOffset(offset, sz)
			}
		}
		x.String(m.GetToLang())
		if m.GetTone() != nil {
			x.String(m.GetTone().Value)
		}

	default:
		// log.Errorf("")
	}

	return nil
}

