// TLChannelsGetMessages
// /////////////////////////////////////////////////////////////////////////////
func (m *TLChannelsGetMessages) Encode(x *EncodeBuf, layer int32) error {
	switch uint32(m.Constructor) {
	case 0xad8c9a23:
		x.UInt(0xad8c9a23)

		// no flags

		m.GetChannel().Encode(x, layer)

		x.Int(int32(CRC32_vector))
		{
			var (
				sz     = int32(0)
				offset = x.GetOffset()
			)
			list2 := m.GetId_VECTORINPUTMESSAGE()
			x.Int(int32(len(list2)))
			for _, v := range list2 {
				err := v.Encode(x, layer)
				if err == nil {
					sz += 1
				}
			}
			x.IntOffset(offset, sz)
		}

	case 0x93d7b347:
		x.UInt(0x93d7b347)

		// no flags

		m.GetChannel().Encode(x, layer)

		x.VectorInt(m.GetId_VECTORINT32())

	default:
		// log.Errorf("")
	}

	return nil
}

