// TLChannelsCreateChannel
// /////////////////////////////////////////////////////////////////////////////
func (m *TLChannelsCreateChannel) Encode(x *EncodeBuf, layer int32) error {
	switch uint32(m.Constructor) {
	case 0x91006707:
		x.UInt(0x91006707)

		// set flags
		var flags uint32 = 0

		if m.GetBroadcast() == true {
			flags |= 1 << 0
		}
		if m.GetMegagroup() == true {
			flags |= 1 << 1
		}
		if m.GetForImport() == true {
			flags |= 1 << 3
		}
		if m.GetForum() == true {
			flags |= 1 << 5
		}

		if m.GetGeoPoint() != nil {
			flags |= 1 << 2
		}
		if m.GetAddress() != nil {
			flags |= 1 << 2
		}
		if m.GetTtlPeriod() != nil {
			flags |= 1 << 4
		}

		x.UInt(flags)

		// flags Debug by @benqi
		x.String(m.GetTitle())
		x.String(m.GetAbout())
		if m.GetGeoPoint() != nil {
			m.GetGeoPoint().Encode(x, layer)
		}

		if m.GetAddress() != nil {
			x.String(m.GetAddress().Value)
		}

		if m.GetTtlPeriod() != nil {
			x.Int(m.GetTtlPeriod().Value)
		}

	case 0x3d5fb10f:
		x.UInt(0x3d5fb10f)

		// set flags
		var flags uint32 = 0

		if m.GetBroadcast() == true {
			flags |= 1 << 0
		}
		if m.GetMegagroup() == true {
			flags |= 1 << 1
		}
		if m.GetForImport() == true {
			flags |= 1 << 3
		}

		if m.GetGeoPoint() != nil {
			flags |= 1 << 2
		}
		if m.GetAddress() != nil {
			flags |= 1 << 2
		}

		x.UInt(flags)

		// flags Debug by @benqi
		x.String(m.GetTitle())
		x.String(m.GetAbout())
		if m.GetGeoPoint() != nil {
			m.GetGeoPoint().Encode(x, layer)
		}

		if m.GetAddress() != nil {
			x.String(m.GetAddress().Value)
		}

	default:
		// log.Errorf("")
	}

	return nil
}

func (m *TLChannelsCreateChannel) CalcByteSize(layer int32) int {
	return 0
}

func (m *TLChannelsCreateChannel) Decode(dBuf *DecodeBuf) error {
	switch uint32(m.Constructor) {
	case 0x91006707:

		flags := dBuf.UInt()
		_ = flags

		// flags Debug by @benqi
		if (flags & (1 << 0)) != 0 {
			m.Broadcast = true
		}
		if (flags & (1 << 1)) != 0 {
			m.Megagroup = true
		}
		if (flags & (1 << 3)) != 0 {
			m.ForImport = true
		}
		if (flags & (1 << 5)) != 0 {
			m.Forum = true
		}
		m.Title = dBuf.String()
		m.About = dBuf.String()
		if (flags & (1 << 2)) != 0 {
			m8 := &InputGeoPoint{}
			m8.Decode(dBuf)
			m.GeoPoint = m8
		}
		if (flags & (1 << 2)) != 0 {
			m.Address = &wrapperspb.StringValue{Value: dBuf.String()}
		}

		if (flags & (1 << 4)) != 0 {
			m.TtlPeriod = &wrapperspb.Int32Value{Value: dBuf.Int()}
		}

		return dBuf.GetError()
	case 0x3d5fb10f:

		flags := dBuf.UInt()
		_ = flags

		// flags Debug by @benqi
		if (flags & (1 << 0)) != 0 {
			m.Broadcast = true
		}
		if (flags & (1 << 1)) != 0 {
			m.Megagroup = true
		}
		if (flags & (1 << 3)) != 0 {
			m.ForImport = true
		}
		m.Title = dBuf.String()
		m.About = dBuf.String()
		if (flags & (1 << 2)) != 0 {
			m7 := &InputGeoPoint{}
			m7.Decode(dBuf)
			m.GeoPoint = m7
		}
		if (flags & (1 << 2)) != 0 {
			m.Address = &wrapperspb.StringValue{Value: dBuf.String()}
		}

		return dBuf.GetError()

	default:
		// log.Errorf("")
	}
	return dBuf.GetError()
}

