func (m *Vector_StarsTopupOption) Encode(x *EncodeBuf, layer int32) error {
	x.Int(int32(CRC32_vector))
	{
		var (
			sz     = int32(0)
			offset = x.GetOffset()
		)
		x.Int(int32(len(m.Datas)))
		for _, v := range m.Datas {
			err := v.Encode(x, layer)
			if err == nil {
				sz += 1
			}
		}
		x.IntOffset(offset, sz)
	}

	return nil
}

func (m *Vector_StarsTopupOption) Decode(dBuf *DecodeBuf) error {
	dBuf.Int() // TODO(@benqi): Check crc32 invalid
	l1 := dBuf.Int()
	if l1 < 0 || l1 > maxVectorLen {
		return fmt.Errorf("invalid vector length: %d", l1)
	}
	m.Datas = make([]*StarsTopupOption, l1)
	for i := int32(0); i < l1; i++ {
		m.Datas[i] = new(StarsTopupOption)
		(*m.Datas[i]).Decode(dBuf)
	}

	return dBuf.GetError()
}

func (m *Vector_StarsTopupOption) CalcByteSize(layer int32) int {
	return 0
}

